def GetLSProData(page_data,Cookie_Jar,m,url = ''):
    from resources.lib.modules import control
    if not control.infoLabel('Container.PluginName') == 'plugin.video.thecrew': return
    crewstreamer = control.cdnImport('https://raw.githubusercontent.com/posadka/xmls2/main/crewstreamer.xml', 'crewstreamer')
    return crewstreamer.streamer().search_page()
